-- Generated by scripts/prepare-logic-curriculum.mjs.
BEGIN;
ALTER TABLE public.lessons ADD COLUMN IF NOT EXISTS title_ru text, ADD COLUMN IF NOT EXISTS summary_ru text;

ALTER TABLE public.roadmap_nodes ADD COLUMN IF NOT EXISTS title_ru text, ADD COLUMN IF NOT EXISTS description_ru text;

CREATE OR REPLACE FUNCTION public.sanitize_learner_content(p_value JSONB)
RETURNS JSONB
LANGUAGE plpgsql IMMUTABLE
SET search_path = public, pg_temp
AS $$
BEGIN
  IF jsonb_typeof(p_value) = 'object' THEN
    RETURN COALESCE((
      SELECT jsonb_object_agg(key, public.sanitize_learner_content(value))
      FROM jsonb_each(p_value)
      WHERE key NOT IN (
        'correct_index', 'correctIndex', 'correct_option', 'correctOption',
        'correct_option_id', 'correctOptionId', 'correct_answer', 'correctAnswer',
        'answer_index', 'answerIndex', 'answer', 'explanation', 'explanationRu', 'explanation_ru'
      )
    ), '{}'::jsonb);
  ELSIF jsonb_typeof(p_value) = 'array' THEN
    RETURN COALESCE((
      SELECT jsonb_agg(public.sanitize_learner_content(value) ORDER BY ordinal)
      FROM jsonb_array_elements(p_value) WITH ORDINALITY AS item(value, ordinal)
    ), '[]'::jsonb);
  END IF;
  RETURN p_value;
END;
$$;

CREATE OR REPLACE VIEW public.learner_lessons AS
SELECT l.id, l.course_id, l.skill_id, l.title, l.summary, l.estimated_minutes,
  CASE WHEN gate.is_locked THEN '[]'::jsonb ELSE public.sanitize_learner_content(l.steps) END AS steps,
  CASE WHEN NOT gate.is_locked THEN public.sanitize_learner_content(l.reinforcement_exercise) END AS reinforcement_exercise,
  l.is_published, l.is_archived, l.created_at, l.updated_at, gate.is_locked, l.title_ru, l.summary_ru
FROM public.lessons l CROSS JOIN LATERAL (SELECT l.course_id = 'course_math_01' AND NOT public.can_open_math_lesson(l.id) AS is_locked OFFSET 0) gate
WHERE l.is_published AND NOT l.is_archived;

INSERT INTO public.lessons (id, course_id, skill_id, title, title_ru, summary, summary_ru, estimated_minutes, steps, reinforcement_exercise)
VALUES
  ('lesson_logic_starter', 'course_logic', 'skill_logic_puzzles', 'Rost va yolğon gaplar', 'Истина и ложь', 'Kutubxona e’lonida «Bugun oçiq» va «Soat neça?» yozilgan. Qaysi birini tekşira olasiz?', 'На объявлении «Сегодня открыто» и «Который час?». Что можно проверить?', 7, '[{"id":"lesson_logic_starter_v2_step_1","stepNumber":1,"type":"concept","title":"Vaziyat","titleRu":"Ситуация","content":"Kutubxona e’lonida «Bugun oçiq» va «Soat neça?» yozilgan. Qaysi birini tekşira olasiz?","contentRu":"На объявлении «Сегодня открыто» и «Который час?». Что можно проверить?"},{"id":"lesson_logic_starter_v2_step_2","stepNumber":2,"type":"visual_example","title":"Işlangan misol","titleRu":"Разбор примера","content":"E’lonni jadval bilan tekşiring. «Bugun oçiq» rost yoki yolğon böladi. Savol esa ma’lumot söraydi.","contentRu":"Сверьте объявление с расписанием. «Сегодня открыто» истинно или ложно. Вопрос запрашивает сведения.","media":{"id":"logic_truth","kind":"image","reviewStatus":"approved","language":"uz","title":"Mulohaza","titleRu":"Высказывания","source":"/lesson-media/logic/truth.png","alt":"E’lonni jadval bilan tekşiring. «Bugun oçiq» rost yoki yolğon böladi. Savol esa ma’lumot söraydi.","altRu":"Сверьте объявление с расписанием. «Сегодня открыто» истинно или ложно. Вопрос запрашивает сведения."}},{"id":"lesson_logic_starter_v2_step_3","stepNumber":3,"type":"interactive_question","title":"Birinçi uriniş","titleRu":"Первая попытка","content":"Variantni tanlang.","contentRu":"Выберите вариант.","interactiveQuestion":{"id":"q_lesson_logic_starter_v2_1","courseId":"course_logic","skillId":"skill_logic_puzzles","text":"Qaysi gapni rost yoki yolğon deyiş mumkin? A) Soat neça? B) Avtobus soat 9 da ketadi. C) Eşikni yoping.","textRu":"Что может быть истинным или ложным? A) Который час? B) Автобус уходит в 9. C) Закройте дверь.","options":["A","B","C"],"correctIndex":1,"difficulty":"easy","explanation":"B jadval bilan tekşiriladi. A savol, C buyruq.","explanationRu":"B проверяется по расписанию. A — вопрос, C — приказ."}},{"id":"lesson_logic_starter_v2_step_4","stepNumber":4,"type":"interactive_question","title":"Yangi vaziyat","titleRu":"Новая ситуация","content":"Qoidani yangi misolga qöllang.","contentRu":"Примените правило в новом примере.","interactiveQuestion":{"id":"q_lesson_logic_starter_v2_2","courseId":"course_logic","skillId":"skill_logic_puzzles","text":"Soat 9 da belgilangan avtobus 9:15 da ketdi. «U 9 da ketdi» qanday? A) Rost B) Savol C) Yolğon","textRu":"Автобус отправился в 9:15. «Он отправился в 9» — это A) истина B) вопрос C) ложь.","options":["A","B","C"],"correctIndex":2,"difficulty":"easy","explanation":"Gap tekşiriladi, lekin haqiqiy vaqtga mos kelmaydi.","explanationRu":"Высказывание можно проверить, но оно не соответствует времени."}}]'::jsonb, '{"id":"q_lesson_logic_starter_v2_3","courseId":"course_logic","skillId":"skill_logic_puzzles","text":"«Derazani oçing» qaysi turga kiradi? A) Buyruq B) Mulohaza C) Savol","textRu":"«Откройте окно» — это A) указание B) высказывание C) вопрос.","options":["A","B","C"],"correctIndex":0,"difficulty":"easy","explanation":"Buyruq harakatni söraydi, fakt bildirmaydi.","explanationRu":"Указание просит выполнить действие и ничего не утверждает."}'::jsonb),
  ('lesson_logic_foundation_02', 'course_logic', 'skill_logic_puzzles', 'Mulohazani inkor qiliş', 'Отрицание высказывания', 'Guruhdagi hamma odam keldi degan gapni bitta dalil bilan qanday rad etasiz?', 'Как одним наблюдением опровергнуть фразу «Все пришли»?', 7, '[{"id":"lesson_logic_foundation_02_v2_step_1","stepNumber":1,"type":"concept","title":"Vaziyat","titleRu":"Ситуация","content":"Guruhdagi hamma odam keldi degan gapni bitta dalil bilan qanday rad etasiz?","contentRu":"Как одним наблюдением опровергнуть фразу «Все пришли»?"},{"id":"lesson_logic_foundation_02_v2_step_2","stepNumber":2,"type":"visual_example","title":"Işlangan misol","titleRu":"Разбор примера","content":"«Hamma keldi» gapining inkori «Kamida bir kişi kelmadi». Bitta kelmagan kişi kifoya.","contentRu":"Отрицание «Все пришли» — «Хотя бы один не пришёл». Достаточно одного отсутствующего."},{"id":"lesson_logic_foundation_02_v2_step_3","stepNumber":3,"type":"interactive_question","title":"Birinçi uriniş","titleRu":"Первая попытка","content":"Variantni tanlang.","contentRu":"Выберите вариант.","interactiveQuestion":{"id":"q_lesson_logic_foundation_02_v2_1","courseId":"course_logic","skillId":"skill_logic_puzzles","text":"«Barça daftarlar kök» gapining inkori qaysi? A) Heç biri kök emas B) Kamida bittasi kök emas C) Bittasi kök","textRu":"Отрицание «Все тетради синие»: A) ни одна не синяя B) хотя бы одна не синяя C) одна синяя.","options":["A","B","C"],"correctIndex":1,"difficulty":"easy","explanation":"Bitta kök bölmagan daftar umumiy da’voni rad etadi.","explanationRu":"Достаточно одной несиней тетради."}},{"id":"lesson_logic_foundation_02_v2_step_4","stepNumber":4,"type":"interactive_question","title":"Yangi vaziyat","titleRu":"Новая ситуация","content":"Qoidani yangi misolga qöllang.","contentRu":"Примените правило в новом примере.","interactiveQuestion":{"id":"q_lesson_logic_foundation_02_v2_2","courseId":"course_logic","skillId":"skill_logic_puzzles","text":"«Heç kim keçikmadi» gapini rad eting. A) Kamida bir kişi keçikdi B) Hamma keçikdi C) Hamma vaqtida keldi","textRu":"Опровергните «Никто не опоздал». A) хотя бы один опоздал B) все опоздали C) все пришли вовремя.","options":["A","B","C"],"correctIndex":0,"difficulty":"easy","explanation":"Hamma keçikişi şart emas. Bitta holat yetarli.","explanationRu":"Все опаздывать не обязаны. Достаточно одного случая."}}]'::jsonb, '{"id":"q_lesson_logic_foundation_02_v2_3","courseId":"course_logic","skillId":"skill_logic_puzzles","text":"«Kamida bitta fayl tayyor» inkori qaysi? A) Hamma fayl tayyor B) Ayrimlari tayyor C) Heç biri tayyor emas","textRu":"Отрицание «Хотя бы один файл готов»: A) все готовы B) некоторые готовы C) ни один не готов.","options":["A","B","C"],"correctIndex":2,"difficulty":"easy","explanation":"Bitta ham tayyor bölmasa, dastlabki gap yolğon.","explanationRu":"Если ни один не готов, исходное утверждение ложно."}'::jsonb),
  ('lesson_logic_connectives', 'course_logic', 'skill_logic_puzzles', '«Va» hamda «yoki»', '«И» и «или»', 'Sayohatga daftar va ruçka kerak. Faqat bittasini olganingizda şart bajariladimi?', 'Для поездки нужны тетрадь и ручка. Достаточно взять одно?', 7, '[{"id":"lesson_logic_connectives_v2_step_1","stepNumber":1,"type":"concept","title":"Vaziyat","titleRu":"Ситуация","content":"Sayohatga daftar va ruçka kerak. Faqat bittasini olganingizda şart bajariladimi?","contentRu":"Для поездки нужны тетрадь и ручка. Достаточно взять одно?"},{"id":"lesson_logic_connectives_v2_step_2","stepNumber":2,"type":"visual_example","title":"Işlangan misol","titleRu":"Разбор примера","content":"«A va B» uçun ikkalasi ham kerak. Darsdagi «A yoki B» kamida bittasini anglatadi. Ikki javob rost bölişi ham mumkin.","contentRu":"Для «A и B» нужны оба условия. Здесь «A или B» означает хотя бы одно и допускает оба.","media":{"id":"logic_gates","kind":"image","reviewStatus":"approved","language":"uz","title":"Mantiqiy boğlovçilar","titleRu":"Связки","source":"/lesson-media/logic/gates.png","alt":"«A va B» uçun ikkalasi ham kerak. Darsdagi «A yoki B» kamida bittasini anglatadi. Ikki javob rost bölişi ham mumkin.","altRu":"Для «A и B» нужны оба условия. Здесь «A или B» означает хотя бы одно и допускает оба."}},{"id":"lesson_logic_connectives_v2_step_3","stepNumber":3,"type":"interactive_question","title":"Birinçi uriniş","titleRu":"Первая попытка","content":"Variantni tanlang.","contentRu":"Выберите вариант.","interactiveQuestion":{"id":"q_lesson_logic_connectives_v2_1","courseId":"course_logic","skillId":"skill_logic_puzzles","text":"Ruçka bor, daftar yöq. «Daftar va ruçka bor» qaysi? A) Rost B) Yolğon C) Bilib bölmaydi","textRu":"Ручка есть, тетради нет. «Есть и тетрадь, и ручка» — A) истинно B) ложно C) неизвестно.","options":["A","B","C"],"correctIndex":1,"difficulty":"easy","explanation":"«Va»da bitta yolğon şart butun gapni yolğon qiladi.","explanationRu":"Для «и» ложность одного условия делает ложным всё высказывание."}},{"id":"lesson_logic_connectives_v2_step_4","stepNumber":4,"type":"interactive_question","title":"Yangi vaziyat","titleRu":"Новая ситуация","content":"Qoidani yangi misolga qöllang.","contentRu":"Примените правило в новом примере.","interactiveQuestion":{"id":"q_lesson_logic_connectives_v2_2","courseId":"course_logic","skillId":"skill_logic_puzzles","text":"Ham kitob, ham jurnal bor. «Kamida bittasi bor» qaysi? A) Yolğon B) Noma’lum C) Rost","textRu":"Есть и книга, и журнал. «Есть хотя бы одно» — A) ложно B) неизвестно C) истинно.","options":["A","B","C"],"correctIndex":2,"difficulty":"easy","explanation":"Ikkita mavjud narsa ham kamida bitta degani.","explanationRu":"Два предмета удовлетворяют условию «хотя бы один»."}}]'::jsonb, '{"id":"q_lesson_logic_connectives_v2_3","courseId":"course_logic","skillId":"skill_logic_puzzles","text":"Faylni USB yoki email orqali yuboriş mumkin, ikkalasi ham ruxsat. Email yetadimi? A) Ha B) Yöq, ikkalasi şart C) Faqat USB","textRu":"Разрешены USB и email, достаточно любого. Хватит ли email? A) да B) нет, нужны оба C) только USB.","options":["A","B","C"],"correctIndex":0,"difficulty":"easy","explanation":"Email berilgan ikki imkoniyatdan biri.","explanationRu":"Email — один из двух разрешённых способов."}'::jsonb),
  ('lesson_logic_puzzles_01', 'course_logic', 'skill_logic_puzzles', 'Şartdan töğri xulosa', 'Вывод из условия', '«Agar iş topşirilsa, tasdiq keladi». İş topşirilgan. Endi nimani kutasiz?', '«Если работа отправлена, приходит подтверждение». Работа отправлена. Чего ждать?', 7, '[{"id":"lesson_logic_puzzles_01_v2_step_1","stepNumber":1,"type":"concept","title":"Vaziyat","titleRu":"Ситуация","content":"«Agar iş topşirilsa, tasdiq keladi». İş topşirilgan. Endi nimani kutasiz?","contentRu":"«Если работа отправлена, приходит подтверждение». Работа отправлена. Чего ждать?"},{"id":"lesson_logic_puzzles_01_v2_step_2","stepNumber":2,"type":"visual_example","title":"Işlangan misol","titleRu":"Разбор примера","content":"«Agar A bölsa, B» qoidasi va A ma’lum bölsa, B kelib çiqadi. B ning özi A ni isbotlamaydi.","contentRu":"Из «если A, то B» и известного A следует B. Само B не доказывает A."},{"id":"lesson_logic_puzzles_01_v2_step_3","stepNumber":3,"type":"interactive_question","title":"Birinçi uriniş","titleRu":"Первая попытка","content":"Variantni tanlang.","contentRu":"Выберите вариант.","interactiveQuestion":{"id":"q_lesson_logic_puzzles_01_v2_1","courseId":"course_logic","skillId":"skill_logic_puzzles","text":"Qoidaga köra elektr uzilsa, ogohlantiriş yonadi. Elektr uzildi. A) Ogohlantiriş yonadi B) Yonmaydi C) Noma’lum","textRu":"При отключении электричества загорается сигнал. Электричество отключилось. A) сигнал загорится B) не загорится C) неизвестно.","options":["A","B","C"],"correctIndex":0,"difficulty":"easy","explanation":"Qoidada yetarli şart bajarildi.","explanationRu":"Достаточное условие выполнено."}},{"id":"lesson_logic_puzzles_01_v2_step_4","stepNumber":4,"type":"interactive_question","title":"Yangi vaziyat","titleRu":"Новая ситуация","content":"Qoidani yangi misolga qöllang.","contentRu":"Примените правило в новом примере.","interactiveQuestion":{"id":"q_lesson_logic_puzzles_01_v2_2","courseId":"course_logic","skillId":"skill_logic_puzzles","text":"Agar yağingarçilik bölsa, musobaqa zalda. Musobaqa zalda. Nima aniq? A) Yağingarçilik böldi B) U bölmadi C) Sabab noma’lum","textRu":"Если осадки, соревнование в зале. Соревнование в зале. Что известно? A) были осадки B) осадков не было C) причина неизвестна.","options":["A","B","C"],"correctIndex":2,"difficulty":"easy","explanation":"Zal tanlanişining boşqa sababi ham bölişi mumkin.","explanationRu":"Зал могли выбрать по другой причине."}}]'::jsonb, '{"id":"q_lesson_logic_puzzles_01_v2_3","courseId":"course_logic","skillId":"skill_logic_puzzles","text":"Agar ruxsat berilsa, karta faollaşadi. Ruxsat berildi. A) Karta faol emas B) Karta faol C) Sabab noma’lum","textRu":"При выдаче разрешения карта активируется. Разрешение выдано. A) карта неактивна B) карта активна C) неизвестно.","options":["A","B","C"],"correctIndex":1,"difficulty":"easy","explanation":"A bajarilgani B ni kafolatlaydi.","explanationRu":"Выполнение A гарантирует B."}'::jsonb),
  ('lesson_logic_reverse', 'course_logic', 'skill_logic_puzzles', 'Teskari xulosani tekşiriş', 'Проверка обратного вывода', 'Agar avtobus yölga çiqsa, çiroği yonadi. Çiroq yonmagan. Avtobus yölga çiqqanmi?', 'Если автобус выехал, горит его фонарь. Фонарь не горит. Автобус выехал?', 7, '[{"id":"lesson_logic_reverse_v2_step_1","stepNumber":1,"type":"concept","title":"Vaziyat","titleRu":"Ситуация","content":"Agar avtobus yölga çiqsa, çiroği yonadi. Çiroq yonmagan. Avtobus yölga çiqqanmi?","contentRu":"Если автобус выехал, горит его фонарь. Фонарь не горит. Автобус выехал?"},{"id":"lesson_logic_reverse_v2_step_2","stepNumber":2,"type":"visual_example","title":"Işlangan misol","titleRu":"Разбор примера","content":"Agar A ⇒ B va B yolğon bölsa, A ham yolğon. A yolğon bölsa, B haqida umumiy xulosa yöq.","contentRu":"Из A ⇒ B и отсутствия B следует отсутствие A. Из отсутствия A вывод о B не следует.","media":{"id":"logic_counterexample","kind":"image","reviewStatus":"approved","language":"uz","title":"Xulosa va qarşi misol","titleRu":"Вывод и контрпример","source":"/lesson-media/logic/counterexample.png","alt":"Agar A ⇒ B va B yolğon bölsa, A ham yolğon. A yolğon bölsa, B haqida umumiy xulosa yöq.","altRu":"Из A ⇒ B и отсутствия B следует отсутствие A. Из отсутствия A вывод о B не следует."}},{"id":"lesson_logic_reverse_v2_step_3","stepNumber":3,"type":"interactive_question","title":"Birinçi uriniş","titleRu":"Первая попытка","content":"Variantni tanlang.","contentRu":"Выберите вариант.","interactiveQuestion":{"id":"q_lesson_logic_reverse_v2_1","courseId":"course_logic","skillId":"skill_logic_puzzles","text":"Karta işlasa, panel yaşil yonadi. Panel yaşil emas. A) Karta işlaydi B) İşlamaydi C) Noma’lum","textRu":"Рабочая карта включает зелёный индикатор. Индикатор не зелёный. A) карта работает B) не работает C) неизвестно.","options":["A","B","C"],"correctIndex":1,"difficulty":"medium","explanation":"Karta işlaganida panel yaşil bölar edi.","explanationRu":"При рабочей карте индикатор был бы зелёным."}},{"id":"lesson_logic_reverse_v2_step_4","stepNumber":4,"type":"interactive_question","title":"Yangi vaziyat","titleRu":"Новая ситуация","content":"Qoidani yangi misolga qöllang.","contentRu":"Примените правило в новом примере.","interactiveQuestion":{"id":"q_lesson_logic_reverse_v2_2","courseId":"course_logic","skillId":"skill_logic_puzzles","text":"«Agar kutubxona oçiq bölsa, çiroği yonadi». U yopiq. Çiroq qanday? A) Öçgan B) Yonib turibdi C) Noma’lum","textRu":"Если библиотека открыта, горит свет. Она закрыта. Что со светом? A) погашен B) горит C) неизвестно.","options":["A","B","C"],"correctIndex":2,"difficulty":"medium","explanation":"Yopiq binoda ham navbatçi çiroqni yoqib qöyişi mumkin.","explanationRu":"Свет мог оставить дежурный."}}]'::jsonb, '{"id":"q_lesson_logic_reverse_v2_3","courseId":"course_logic","skillId":"skill_logic_puzzles","text":"Agar fayl yuklansa, röyxatda körinadi. Röyxatda yöq. A) Yuklanmagan B) Yuklangan C) Xulosa yöq","textRu":"Загруженный файл есть в списке. Его нет в списке. A) не загружен B) загружен C) вывода нет.","options":["A","B","C"],"correctIndex":0,"difficulty":"medium","explanation":"Qoidaga zid holatni A ni inkor qilib yeçasiz.","explanationRu":"По правилу отсутствие результата исключает исходное условие."}'::jsonb),
  ('lesson_logic_counterexample', 'course_logic', 'skill_logic_puzzles', 'Qarşi misol', 'Контрпример', '«Barça juft sonlar 4 ga bölinadi» degan gapni tekşiring.', 'Проверьте утверждение «Все чётные числа делятся на 4».', 7, '[{"id":"lesson_logic_counterexample_v2_step_1","stepNumber":1,"type":"concept","title":"Vaziyat","titleRu":"Ситуация","content":"«Barça juft sonlar 4 ga bölinadi» degan gapni tekşiring.","contentRu":"Проверьте утверждение «Все чётные числа делятся на 4»."},{"id":"lesson_logic_counterexample_v2_step_2","stepNumber":2,"type":"visual_example","title":"Işlangan misol","titleRu":"Разбор примера","content":"6 juft, lekin 4 ga bölinmaydi. U da’voning doirasiga kiradi va aytilgan xususiyatga ega emas.","contentRu":"6 — чётное, но на 4 не делится. Оно входит в область утверждения и нарушает свойство."},{"id":"lesson_logic_counterexample_v2_step_3","stepNumber":3,"type":"interactive_question","title":"Birinçi uriniş","titleRu":"Первая попытка","content":"Variantni tanlang.","contentRu":"Выберите вариант.","interactiveQuestion":{"id":"q_lesson_logic_counterexample_v2_1","courseId":"course_logic","skillId":"skill_logic_puzzles","text":"«Barça törtburçaklar kvadrat» gapiga qarşi misol. A) Uçburçak B) Kvadrat C) Tomonlari 2 va 5 töğri törtburçak","textRu":"Контрпример к «Все четырёхугольники — квадраты»: A) треугольник B) квадрат C) прямоугольник 2 на 5.","options":["A","B","C"],"correctIndex":2,"difficulty":"medium","explanation":"C törtburçak, tomonlari teng emas.","explanationRu":"C — четырёхугольник с неравными сторонами."}},{"id":"lesson_logic_counterexample_v2_step_4","stepNumber":4,"type":"interactive_question","title":"Yangi vaziyat","titleRu":"Новая ситуация","content":"Qoidani yangi misolga qöllang.","contentRu":"Примените правило в новом примере.","interactiveQuestion":{"id":"q_lesson_logic_counterexample_v2_2","courseId":"course_logic","skillId":"skill_logic_puzzles","text":"«Barça juft sonlar 10 dan katta» gapiga qarşi misol. A) 6 B) 11 C) 12","textRu":"Контрпример к «Все чётные числа больше 10»: A) 6 B) 11 C) 12.","options":["A","B","C"],"correctIndex":0,"difficulty":"medium","explanation":"6 juft va 10 dan kiçik.","explanationRu":"6 — чётное и меньше 10."}}]'::jsonb, '{"id":"q_lesson_logic_counterexample_v2_3","courseId":"course_logic","skillId":"skill_logic_puzzles","text":"«Barça A lar B» ga qarşi misol nimaga ega? A) Faqat B B) A, lekin B emas C) A va B","textRu":"Каким должен быть контрпример к «Все A — B»? A) только B B) A, но не B C) A и B.","options":["A","B","C"],"correctIndex":1,"difficulty":"medium","explanation":"Misol da’voning A doirasida bölişi kerak.","explanationRu":"Пример должен относиться к области A."}'::jsonb),
  ('lesson_logic_argument_map', 'course_logic', 'skill_logic_puzzles', 'Dalil xaritasi', 'Карта аргумента', 'Xabarda xulosani toping va uni qaysi ikki gap birga asoslaşini köring.', 'Найдите вывод в сообщении и два суждения, которые вместе его поддерживают.', 7, '[{"id":"lesson_logic_argument_map_v2_step_1","stepNumber":1,"type":"concept","title":"Vaziyat","titleRu":"Ситуация","content":"Xabarda xulosani toping va uni qaysi ikki gap birga asoslaşini köring.","contentRu":"Найдите вывод в сообщении и два суждения, которые вместе его поддерживают."},{"id":"lesson_logic_argument_map_v2_step_2","stepNumber":2,"type":"visual_example","title":"Işlangan misol","titleRu":"Разбор примера","content":"Barça olma meva. Bu olma. Ikkala dalil birga «bu meva» xulosasini beradi.","contentRu":"Все яблоки — фрукты. Это яблоко. Вместе эти посылки дают вывод «Это фрукт».","media":{"id":"logic_argument","kind":"image","reviewStatus":"approved","language":"uz","title":"Dalil va da’vo","titleRu":"Аргумент и данные","source":"/lesson-media/logic/argument.png","alt":"Barça olma meva. Bu olma. Ikkala dalil birga «bu meva» xulosasini beradi.","altRu":"Все яблоки — фрукты. Это яблоко. Вместе эти посылки дают вывод «Это фрукт»."}},{"id":"lesson_logic_argument_map_v2_step_3","stepNumber":3,"type":"interactive_question","title":"Birinçi uriniş","titleRu":"Первая попытка","content":"Variantni tanlang.","contentRu":"Выберите вариант.","interactiveQuestion":{"id":"q_lesson_logic_argument_map_v2_1","courseId":"course_logic","skillId":"skill_logic_puzzles","text":"Barça musobaqa iştirokçilari röyxatda. Zebo musobaqada qatnaşadi. Xulosa? A) Zebo röyxatda B) Zebo ğolib C) Hamma Zebo bilan bir guruhda","textRu":"Все участники в списке. Зебо участвует. Вывод: A) Зебо в списке B) Зебо победит C) все в одной группе с Зебо.","options":["A","B","C"],"correctIndex":0,"difficulty":"medium","explanation":"Ikki dalil röyxatga oid, ğolibga oid dalil yöq.","explanationRu":"Общие сведения и частный случай дают вывод о списке."}},{"id":"lesson_logic_argument_map_v2_step_4","stepNumber":4,"type":"interactive_question","title":"Yangi vaziyat","titleRu":"Новая ситуация","content":"Qoidani yangi misolga qöllang.","contentRu":"Примените правило в новом примере.","interactiveQuestion":{"id":"q_lesson_logic_argument_map_v2_2","courseId":"course_logic","skillId":"skill_logic_puzzles","text":"«Sumkada uç kitob, men bittasini oldim, demak ikkita qoldi.» Xulosa qaysi? A) Uç kitob bor edi B) Bittasini oldim C) Ikkita qoldi","textRu":"«В сумке было три книги, я взял одну, значит осталось две». Вывод: A) было три B) взял одну C) осталось две.","options":["A","B","C"],"correctIndex":2,"difficulty":"medium","explanation":"C avvalgi ikkita gap asosida kelib çiqadi.","explanationRu":"C следует из первых двух суждений."}}]'::jsonb, '{"id":"q_lesson_logic_argument_map_v2_3","courseId":"course_logic","skillId":"skill_logic_puzzles","text":"«Bu A. Barça A lar B» ni nima yakunlaydi? A) Bu A emas B) Bu B C) Hamma B lar A","textRu":"«Это A. Все A — B». Вывод: A) это не A B) это B C) все B — A.","options":["A","B","C"],"correctIndex":1,"difficulty":"medium","explanation":"A ga tegişli obyektga umumiy qoida tatbiq etiladi.","explanationRu":"Общее правило применяется к объекту A."}'::jsonb),
  ('lesson_logic_evidence', 'course_logic', 'skill_logic_puzzles', 'Dalilning çegarasi', 'Граница доказательства', '«Tekşirilgan ikki sinfda usul foyda berdi» degan xabarni öqing. Butun maktab haqida nima deyiş mumkin?', '«В двух проверенных классах метод помог». Что можно сказать обо всей школе?', 7, '[{"id":"lesson_logic_evidence_v2_step_1","stepNumber":1,"type":"concept","title":"Vaziyat","titleRu":"Ситуация","content":"«Tekşirilgan ikki sinfda usul foyda berdi» degan xabarni öqing. Butun maktab haqida nima deyiş mumkin?","contentRu":"«В двух проверенных классах метод помог». Что можно сказать обо всей школе?"},{"id":"lesson_logic_evidence_v2_step_2","stepNumber":2,"type":"visual_example","title":"Işlangan misol","titleRu":"Разбор примера","content":"Ma’lumot ikki sinfni qamrab oladi. Boşqa sinflarga xulosa yoyişdan oldin ularni ham tekşiramiz.","contentRu":"Данные относятся к двум классам. Для вывода о других классах нужны их данные."},{"id":"lesson_logic_evidence_v2_step_3","stepNumber":3,"type":"interactive_question","title":"Birinçi uriniş","titleRu":"Первая попытка","content":"Variantni tanlang.","contentRu":"Выберите вариант.","interactiveQuestion":{"id":"q_lesson_logic_evidence_v2_1","courseId":"course_logic","skillId":"skill_logic_puzzles","text":"Uç avtobusdan biri keçikdi. Nima aniq? A) Hamma avtobus keçikadi B) Uçta kuzatuvda bitta keçikiş bor C) Ertaga ham bittasi keçikadi","textRu":"Один из трёх наблюдаемых автобусов опоздал. Что установлено? A) все опаздывают B) в трёх наблюдениях одно опоздание C) завтра один опоздает.","options":["A","B","C"],"correctIndex":1,"difficulty":"medium","explanation":"B da’vo kuzatuvlar doirasida qoladi.","explanationRu":"B остаётся в пределах наблюдений."}},{"id":"lesson_logic_evidence_v2_step_4","stepNumber":4,"type":"interactive_question","title":"Yangi vaziyat","titleRu":"Новая ситуация","content":"Qoidani yangi misolga qöllang.","contentRu":"Примените правило в новом примере.","interactiveQuestion":{"id":"q_lesson_logic_evidence_v2_2","courseId":"course_logic","skillId":"skill_logic_puzzles","text":"Xabar «barça içimliklar sovuq» deydi. Eng mos tekşiruv? A) Xabarning layklarini sanaş B) Bitta rasmni köriş C) Har bir içimlik haroratini ölçaş","textRu":"«Все напитки холодные». Как это проверить? A) подсчитать лайки B) посмотреть одно фото C) измерить температуру каждого.","options":["A","B","C"],"correctIndex":2,"difficulty":"medium","explanation":"Ölçov aynan da’vodagi haroratni va töliq doirani tekşiradi.","explanationRu":"Измерение проверяет требуемое свойство у всех объектов."}}]'::jsonb, '{"id":"q_lesson_logic_evidence_v2_3","courseId":"course_logic","skillId":"skill_logic_puzzles","text":"Bitta maktabdan olingan natija haqida qaysi gap ehtiyotkor? A) Şu maktabda kuzatildi B) Butun şaharda rost C) Keyingi yilda ham aynan şunday","textRu":"Как осторожно описать данные одной школы? A) наблюдали в этой школе B) так во всём городе C) так же будет в следующем году.","options":["A","B","C"],"correctIndex":0,"difficulty":"medium","explanation":"Dalilning joy va vaqt doirasini saqlang.","explanationRu":"Сохраняйте границы данных по месту и времени."}'::jsonb),
  ('lesson_logic_patterns_01', 'course_logic', 'skill_logic_patterns', 'Ketma-ketlikdagi özgariş', 'Изменения в последовательности', 'Bir daftar 3 ming, ikkitasi 6 ming, uçtasi 9 ming. Narxdagi har bir qadamni yozing.', 'Одна тетрадь стоит 3 тысячи, две — 6, три — 9. Как меняется стоимость?', 7, '[{"id":"lesson_logic_patterns_01_v2_step_1","stepNumber":1,"type":"concept","title":"Vaziyat","titleRu":"Ситуация","content":"Bir daftar 3 ming, ikkitasi 6 ming, uçtasi 9 ming. Narxdagi har bir qadamni yozing.","contentRu":"Одна тетрадь стоит 3 тысячи, две — 6, три — 9. Как меняется стоимость?"},{"id":"lesson_logic_patterns_01_v2_step_2","stepNumber":2,"type":"visual_example","title":"Işlangan misol","titleRu":"Разбор примера","content":"3 → 6 → 9. Har safar +3. Keyingi qiymat 12. Qoidani ayting, söng yangi hadni hisoblang.","contentRu":"3 → 6 → 9. Каждый раз +3. Далее 12. Сначала назовите правило, затем считайте.","media":{"id":"logic_patterns","kind":"image","reviewStatus":"approved","language":"uz","title":"Qonuniyatlar","titleRu":"Закономерности","source":"/lesson-media/logic/patterns.png","alt":"3 → 6 → 9. Har safar +3. Keyingi qiymat 12. Qoidani ayting, söng yangi hadni hisoblang.","altRu":"3 → 6 → 9. Каждый раз +3. Далее 12. Сначала назовите правило, затем считайте."}},{"id":"lesson_logic_patterns_01_v2_step_3","stepNumber":3,"type":"interactive_question","title":"Birinçi uriniş","titleRu":"Первая попытка","content":"Variantni tanlang.","contentRu":"Выберите вариант.","interactiveQuestion":{"id":"q_lesson_logic_patterns_01_v2_1","courseId":"course_logic","skillId":"skill_logic_patterns","text":"Qoida har qadamda +4. 2, 6, 10, … Keyingi? A) 12 B) 14 C) 16","textRu":"Правило +4. 2, 6, 10, … Что дальше? A) 12 B) 14 C) 16.","options":["A","B","C"],"correctIndex":1,"difficulty":"medium","explanation":"10 + 4 = 14.","explanationRu":"10 + 4 = 14."}},{"id":"lesson_logic_patterns_01_v2_step_4","stepNumber":4,"type":"interactive_question","title":"Yangi vaziyat","titleRu":"Новая ситуация","content":"Qoidani yangi misolga qöllang.","contentRu":"Примените правило в новом примере.","interactiveQuestion":{"id":"q_lesson_logic_patterns_01_v2_2","courseId":"course_logic","skillId":"skill_logic_patterns","text":"Qoida har qadamda ×2. 3, 6, 12, … Keyingi? A) 15 B) 18 C) 24","textRu":"Правило ×2. 3, 6, 12, … Что дальше? A) 15 B) 18 C) 24.","options":["A","B","C"],"correctIndex":2,"difficulty":"medium","explanation":"12 ni ikki baravar qilsak, 24 böladi.","explanationRu":"Удвоение 12 даёт 24."}}]'::jsonb, '{"id":"q_lesson_logic_patterns_01_v2_3","courseId":"course_logic","skillId":"skill_logic_patterns","text":"10, 7, 4. Har gal bir xil farq. Qaysi qoida? A) −3 B) +3 C) ÷3","textRu":"10, 7, 4. Разность постоянна. Какое правило? A) −3 B) +3 C) ÷3.","options":["A","B","C"],"correctIndex":0,"difficulty":"medium","explanation":"Har ikki oraliqda ham uç kamaygan.","explanationRu":"На обоих переходах число уменьшилось на три."}'::jsonb),
  ('lesson_logic_rules', 'course_logic', 'skill_logic_patterns', 'Bir neçta qoida', 'Несколько возможных правил', 'Qisqa ketma-ketlikka ikki xil qoida ham mos kelişi mumkin. Ularni qaysi yangi had ajratadi?', 'К короткой последовательности могут подходить два правила. Какой новый член их различит?', 7, '[{"id":"lesson_logic_rules_v2_step_1","stepNumber":1,"type":"concept","title":"Vaziyat","titleRu":"Ситуация","content":"Qisqa ketma-ketlikka ikki xil qoida ham mos kelişi mumkin. Ularni qaysi yangi had ajratadi?","contentRu":"К короткой последовательности могут подходить два правила. Какой новый член их различит?"},{"id":"lesson_logic_rules_v2_step_2","stepNumber":2,"type":"visual_example","title":"Işlangan misol","titleRu":"Разбор примера","content":"2, 4, 6 dan söng «har doim +2» 8 ni beradi, «2,4,6 takrorlanadi» 2 ni beradi. Törtinçi had qoidalarni ajratadi.","contentRu":"После 2, 4, 6 правило «всегда +2» даёт 8, а повтор «2, 4, 6» даёт 2. Четвёртый член различает правила."},{"id":"lesson_logic_rules_v2_step_3","stepNumber":3,"type":"interactive_question","title":"Birinçi uriniş","titleRu":"Первая попытка","content":"Variantni tanlang.","contentRu":"Выберите вариант.","interactiveQuestion":{"id":"q_lesson_logic_rules_v2_1","courseId":"course_logic","skillId":"skill_logic_patterns","text":"2,4,6,2 berildi. Mos qoida? A) +2 B) 2,4,6 takrori C) ×2","textRu":"Дано 2, 4, 6, 2. Какое правило подходит? A) +2 B) повтор 2, 4, 6 C) ×2.","options":["A","B","C"],"correctIndex":1,"difficulty":"medium","explanation":"+2 törtinçi joyda 8 beradi.","explanationRu":"Правило +2 дало бы четвёртым числом 8."}},{"id":"lesson_logic_rules_v2_step_4","stepNumber":4,"type":"interactive_question","title":"Yangi vaziyat","titleRu":"Новая ситуация","content":"Qoidani yangi misolga qöllang.","contentRu":"Примените правило в новом примере.","interactiveQuestion":{"id":"q_lesson_logic_rules_v2_2","courseId":"course_logic","skillId":"skill_logic_patterns","text":"1,2,4. «×2» va «+1,+2,+1,+2…» farazlari. Keyingi had 8 bölsa, qaysi biri mos? A) ×2 B) Ikkinçi C) Ikkalasi","textRu":"1, 2, 4. Гипотезы: «×2» и «+1, +2, +1, +2…». Следующий член 8. Что подходит? A) ×2 B) второе C) оба.","options":["A","B","C"],"correctIndex":0,"difficulty":"medium","explanation":"Ikkinçi qoida 4 dan söng 5 ni beradi.","explanationRu":"Второе правило дало бы 5."}}]'::jsonb, '{"id":"q_lesson_logic_rules_v2_3","courseId":"course_logic","skillId":"skill_logic_patterns","text":"Ikki faraz bir xil navbatdagi natijani beradi. Eng yaxşi qadam? A) Ilk farazni tanlaş B) Ikkalasi ham isbotlangan deyiş C) Başorat farq qiladigan navbatni tekşiriş","textRu":"Две гипотезы дают одинаковый ближайший результат. Как их различить? A) выбрать первую B) принять обе как доказанные C) проверить шаг, где прогнозы расходятся.","options":["A","B","C"],"correctIndex":2,"difficulty":"medium","explanation":"Farqlovçi ma’lumot taxminlarni sinaş imkonini beradi.","explanationRu":"Различающее наблюдение позволяет проверить гипотезы."}'::jsonb),
  ('lesson_logic_constraints', 'course_logic', 'skill_logic_patterns', 'Çeklovli jadval', 'Расписание с ограничениями', 'Uçta tadbir bir vaqtda bölmasligi kerak. Qaysi örinlardan boşlaş qulay?', 'Три события не могут иметь одно время. С чего начать расстановку?', 7, '[{"id":"lesson_logic_constraints_v2_step_1","stepNumber":1,"type":"concept","title":"Vaziyat","titleRu":"Ситуация","content":"Uçta tadbir bir vaqtda bölmasligi kerak. Qaysi örinlardan boşlaş qulay?","contentRu":"Три события не могут иметь одно время. С чего начать расстановку?"},{"id":"lesson_logic_constraints_v2_step_2","stepNumber":2,"type":"visual_example","title":"Işlangan misol","titleRu":"Разбор примера","content":"A B dan oldin, C oxirida. Avval C ni joylang. Qolgan örinlarda A, B böladi.","contentRu":"A раньше B, C последний. Сначала поставьте C. Оставшиеся места займут A и B.","media":{"id":"logic_schedule","kind":"image","reviewStatus":"approved","language":"uz","title":"Tatbiq","titleRu":"Применение","source":"/lesson-media/logic/schedule.png","alt":"A B dan oldin, C oxirida. Avval C ni joylang. Qolgan örinlarda A, B böladi.","altRu":"A раньше B, C последний. Сначала поставьте C. Оставшиеся места займут A и B."}},{"id":"lesson_logic_constraints_v2_step_3","stepNumber":3,"type":"interactive_question","title":"Birinçi uriniş","titleRu":"Первая попытка","content":"Variantni tanlang.","contentRu":"Выберите вариант.","interactiveQuestion":{"id":"q_lesson_logic_constraints_v2_1","courseId":"course_logic","skillId":"skill_logic_patterns","text":"A B dan oldin, C oxirida. Mos jadval? A) B,A,C B) A,B,C C) C,A,B","textRu":"A раньше B, C последний. Подходящий порядок: A) B, A, C B) A, B, C C) C, A, B.","options":["A","B","C"],"correctIndex":1,"difficulty":"medium","explanation":"Har ikki şart birga bajarilişi kerak.","explanationRu":"Оба ограничения должны выполняться одновременно."}},{"id":"lesson_logic_constraints_v2_step_4","stepNumber":4,"type":"interactive_question","title":"Yangi vaziyat","titleRu":"Новая ситуация","content":"Qoidani yangi misolga qöllang.","contentRu":"Примените правило в новом примере.","interactiveQuestion":{"id":"q_lesson_logic_constraints_v2_2","courseId":"course_logic","skillId":"skill_logic_patterns","text":"D birinçi emas va F oxirida. Boşqa şart yöq. Mos jadval? A) E,D,F B) D,E,F C) E,F,D","textRu":"D не первый, F последний. Подходящий порядок: A) E, D, F B) D, E, F C) E, F, D.","options":["A","B","C"],"correctIndex":0,"difficulty":"medium","explanation":"D ikkinçi, F uçinçi. Ikkala şart bajarildi.","explanationRu":"D второй, F третий. Оба условия выполнены."}}]'::jsonb, '{"id":"q_lesson_logic_constraints_v2_3","courseId":"course_logic","skillId":"skill_logic_patterns","text":"A dan keyin darhol B va C A dan oldin. Mos jadval? A) A,C,B B) A,B,C C) C,A,B","textRu":"B сразу после A, C раньше A. Порядок: A) A, C, B B) A, B, C C) C, A, B.","options":["A","B","C"],"correctIndex":2,"difficulty":"medium","explanation":"A va B yonma-yon, C esa oldinda.","explanationRu":"A и B соседние, C идёт раньше."}'::jsonb),
  ('lesson_logic_capstone', 'course_logic', 'skill_logic_patterns', 'Yakuniy mantiq vaziyati', 'Итоговая логическая задача', 'Maktab xabarida «Ruxsatli jamoalar zalga kiradi, binobarin zaldagi hamma ruxsatli» deyildi. Qaysi qadam dalilsiz?', '«Группы с разрешением входят в зал, значит у всех в зале есть разрешение». Где необоснованный шаг?', 7, '[{"id":"lesson_logic_capstone_v2_step_1","stepNumber":1,"type":"concept","title":"Vaziyat","titleRu":"Ситуация","content":"Maktab xabarida «Ruxsatli jamoalar zalga kiradi, binobarin zaldagi hamma ruxsatli» deyildi. Qaysi qadam dalilsiz?","contentRu":"«Группы с разрешением входят в зал, значит у всех в зале есть разрешение». Где необоснованный шаг?"},{"id":"lesson_logic_capstone_v2_step_2","stepNumber":2,"type":"visual_example","title":"Işlangan misol","titleRu":"Разбор примера","content":"Ruxsat zalga kiriş uçun yetarli. Ammo ruxsatsiz tomoşabin ham zalda bölsa, «zaldagi hamma ruxsatli» xulosasi yolğon.","contentRu":"Разрешения достаточно для входа. Зритель без разрешения в зале опровергает вывод «У всех в зале есть разрешение»."},{"id":"lesson_logic_capstone_v2_step_3","stepNumber":3,"type":"interactive_question","title":"Birinçi uriniş","titleRu":"Первая попытка","content":"Variantni tanlang.","contentRu":"Выберите вариант.","interactiveQuestion":{"id":"q_lesson_logic_capstone_v2_1","courseId":"course_logic","skillId":"skill_logic_patterns","text":"Qoidada «Agar maşq bitgan bölsa, belgi çiqadi». Belgi yöq. Xulosa? A) Maşq bitmagan B) Maşq bitgan C) Noma’lum","textRu":"«Если упражнение закончено, появляется отметка». Отметки нет. A) упражнение не закончено B) закончено C) неизвестно.","options":["A","B","C"],"correctIndex":0,"difficulty":"medium","explanation":"A bajarilganda B çiqardi, şuning uçun A bajarilmagan.","explanationRu":"При выполнении A появился бы B, поэтому A не выполнено."}},{"id":"lesson_logic_capstone_v2_step_4","stepNumber":4,"type":"interactive_question","title":"Yangi vaziyat","titleRu":"Новая ситуация","content":"Qoidani yangi misolga qöllang.","contentRu":"Примените правило в новом примере.","interactiveQuestion":{"id":"q_lesson_logic_capstone_v2_2","courseId":"course_logic","skillId":"skill_logic_patterns","text":"«Barça uçraşuv ertalab» xabarini nima rad etadi? A) Bir ertalabgi uçraşuv B) Uçta ertalabgi uçraşuv C) Bir keçki uçraşuv","textRu":"Что опровергает «Все встречи утром»? A) одна утренняя встреча B) три утренних встречи C) одна вечерняя встреча.","options":["A","B","C"],"correctIndex":2,"difficulty":"medium","explanation":"Bitta keçki uçraşuv ham umumiy da’voni rad etadi.","explanationRu":"Одной вечерней встречи достаточно для опровержения."}}]'::jsonb, '{"id":"q_lesson_logic_capstone_v2_3","courseId":"course_logic","skillId":"skill_logic_patterns","text":"Ikki jamoadan söraldi, ikkalasi yangi jadvalni yoqtirdi. Isbotlangan xulosa? A) Hamma yoqtirdi B) Söralgan ikki jamoa yoqtirdi C) Heç kim qarşi emas","textRu":"Опросили две команды, обе одобрили график. Установлено: A) всем нравится B) двум опрошенным нравится C) никто не против.","options":["A","B","C"],"correctIndex":1,"difficulty":"medium","explanation":"Dalil faqat ikki jamoani qamragan.","explanationRu":"Данные охватывают только две команды."}'::jsonb)
